using System.Text.Json;
namespace ForensicEdu.Mobile.Core.Models;
public sealed record Paged<T>{public List<T> Items{get;init;}=[];public int Total{get;init;}}
public sealed record Payment{public string Id{get;init;}="";public string OrderId{get;init;}="";public string OrderCode{get;init;}="";public string ProductTitle{get;init;}="";public string BankName{get;init;}="";public decimal Amount{get;init;}public string OperationNumber{get;init;}="";public bool HasVoucher{get;init;}public DateTimeOffset RegisteredAt{get;init;}public JsonElement Status{get;init;}public string StatusLabel=>Status.ToString() switch{"1"=>"Pendiente","2"=>"En revisión","3"=>"Aprobado","4"=>"Rechazado","5"=>"Duplicado","6"=>"Observado",var value=>value};}
public sealed record Certificate{public string CertificateCode{get;init;}="";public string CourseTitle{get;init;}="";public string StudentFullName{get;init;}="";public int AcademicHours{get;init;}public decimal FinalGrade{get;init;}public DateTimeOffset IssueDate{get;init;}public JsonElement Status{get;init;}public string QrValidationUrl{get;init;}="";public string StatusLabel=>Status.ToString() switch{"1"=>"Válido","2"=>"Revocado","3"=>"Anulado","4"=>"Vencido",var s=>s};}
public sealed record LiveEvent{public string Id{get;init;}="";public string Title{get;init;}="";public string Description{get;init;}="";public string Speaker{get;init;}="";public string TimeSlot{get;init;}="";public string AccessStatus{get;init;}="";public DateTimeOffset EventDate{get;init;}public decimal Price{get;init;}}
public sealed record Advisory{public string Id{get;init;}="";public string Title{get;init;}="";public string Specialist{get;init;}="";public string Specialty{get;init;}="";public string Description{get;init;}="";public string WhatsappContact{get;init;}="";public decimal Price{get;init;}}
public sealed record CheckoutInput(string UserId,string ProductId,int ProductType,decimal Amount,string BankName,string OperationNumber,DateTime OperationDate,string AccountHolderName);
public sealed record CheckoutResult(string OrderId,string OrderCode,string Message);
public sealed record LinkResult(string Url);
public sealed record Verification{public bool IsValid{get;init;}public string Student{get;init;}="";public string Course{get;init;}="";public string Status{get;init;}="";public string Message{get;init;}="";public string Code{get;init;}="";public decimal Grade{get;init;}}
